-- CreateEnum: NotificationType
CREATE TYPE "NotificationType" AS ENUM ('TASK_REMINDER', 'TASK_ASSIGNED', 'TASK_COMMENT', 'TASK_OVERDUE', 'TASK_SHARED');

-- AlterTable: Add recurrence fields to tasks
ALTER TABLE "tasks" ADD COLUMN "recurrencePattern" TEXT;
ALTER TABLE "tasks" ADD COLUMN "recurrenceEndDate" TIMESTAMP(3);
ALTER TABLE "tasks" ADD COLUMN "nextRecurrenceDate" TIMESTAMP(3);
ALTER TABLE "tasks" ADD COLUMN "parentRecurringTaskId" TEXT;
ALTER TABLE "tasks" ADD COLUMN "isRecurringTemplate" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "tasks" ADD COLUMN "recurrencePaused" BOOLEAN NOT NULL DEFAULT false;

-- CreateTable: Notification
CREATE TABLE "notifications" (
    "id" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "taskId" TEXT,
    "type" "NotificationType" NOT NULL,
    "message" TEXT NOT NULL,
    "read" BOOLEAN NOT NULL DEFAULT false,
    "snoozedUntil" TIMESTAMP(3),
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "readAt" TIMESTAMP(3),

    CONSTRAINT "notifications_pkey" PRIMARY KEY ("id")
);

-- CreateTable: NotificationSettings
CREATE TABLE "notification_settings" (
    "id" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "enabled" BOOLEAN NOT NULL DEFAULT true,
    "defaultReminderTimes" TEXT[],
    "emailNotifications" BOOLEAN NOT NULL DEFAULT false,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "notification_settings_pkey" PRIMARY KEY ("id")
);

-- CreateIndex: Task recurrence indexes
CREATE INDEX "tasks_parentRecurringTaskId_idx" ON "tasks"("parentRecurringTaskId");
CREATE INDEX "tasks_isRecurringTemplate_nextRecurrenceDate_idx" ON "tasks"("isRecurringTemplate", "nextRecurrenceDate");
CREATE INDEX "tasks_nextRecurrenceDate_idx" ON "tasks"("nextRecurrenceDate");

-- CreateIndex: Notification indexes
CREATE INDEX "notifications_userId_idx" ON "notifications"("userId");
CREATE INDEX "notifications_userId_read_idx" ON "notifications"("userId", "read");
CREATE INDEX "notifications_userId_createdAt_idx" ON "notifications"("userId", "createdAt");
CREATE INDEX "notifications_taskId_idx" ON "notifications"("taskId");

-- CreateIndex: NotificationSettings unique constraint
CREATE UNIQUE INDEX "notification_settings_userId_key" ON "notification_settings"("userId");

-- AddForeignKey: Task recurring instances relation
ALTER TABLE "tasks" ADD CONSTRAINT "tasks_parentRecurringTaskId_fkey" FOREIGN KEY ("parentRecurringTaskId") REFERENCES "tasks"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey: Notification to User
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey: Notification to Task
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_taskId_fkey" FOREIGN KEY ("taskId") REFERENCES "tasks"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey: NotificationSettings to User
ALTER TABLE "notification_settings" ADD CONSTRAINT "notification_settings_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
